	'messages:apierror-changecontentmodel-missingtitle' => 'en:The page you specified doesn\'t exist. To create a new page with a custom content model, use the <kbd>action=edit</kbd> module.',
	'messages:apierror-chunk-too-small' => 'en:Minimum chunk size is $1 {{PLURAL:$1|byte|bytes}} for non-final chunks.',
	'messages:apierror-cidrtoobroad' => 'en:$1 CIDR ranges broader than /$2 are not accepted.',
	'messages:apierror-compare-maintextrequired' => 'en:Parameter <var>$1text-main</var> is required when <var>$1slots</var> contains <kbd>main</kbd> (cannot delete the main slot).',
	'messages:apierror-compare-no-title' => 'en:Cannot pre-save transform without a title. Try specifying <var>fromtitle</var> or <var>totitle</var>.',
